namespace Xr.Category.Api.Messaging;

public static class CategoryBehaviorRecordedTopics
{
    public const string Name = "xr.category.behavior-recorded";

    public const string Group = "xr-category-clickhouse-ingestion";
}

/// <summary>
/// A validated behavior event accepted by the Category API.
/// EventId is supplied by the caller as a stable idempotency key.
/// CorrelationId is generated by the Category API for tracing the ingestion path.
/// </summary>
public sealed record CategoryBehaviorRecordedMessage(
    string EventId,
    string CorrelationId,
    string UserId,
    ulong CategoryId,
    string EventType,
    DateTime EventTimeUtc);
